const source = $('Internal Storage - Prepare keys').item.json;
const markdown = String(source.markdown || '');
const batchSource = { ...source };
delete batchSource.markdown;
const matches = [...markdown.matchAll(/^##\s+Página\s+(\d+)\s*$/gim)];
if (!matches.length) throw new Error('EXTRACAO: Markdown sem marcadores de página');
const pageNumbers = matches.map((match) => Number(match[1]));
if (new Set(pageNumbers).size !== pageNumbers.length) throw new Error('EXTRACAO: marcadores de página duplicados');
const expectedPages = Number(source.metadata && source.metadata.page_count || 0);
const sortedPages = [...pageNumbers].sort((a, b) => a - b);
if (!expectedPages || sortedPages.length !== expectedPages || sortedPages.some((page, index) => page !== index + 1)) throw new Error('EXTRACAO: quantidade ou sequência de páginas divergente dos metadados');
function splitText(text, limit) {
  const pieces = []; let offset = 0;
  while (text.length - offset > limit) {
    const end = offset + limit; const minimum = offset + Math.floor(limit / 2);
    const paragraph = text.lastIndexOf('\n\n', end - 1);
    const newline = text.lastIndexOf('\n', end - 1);
    const space = text.lastIndexOf(' ', end - 1);
    const boundary = paragraph >= minimum ? paragraph + 2 : newline >= minimum ? newline + 1 : space >= minimum ? space + 1 : end;
    pieces.push(text.slice(offset, boundary)); offset = boundary;
  }
  pieces.push(text.slice(offset)); return pieces;
}
const pageChunks = [];
for (let index = 0; index < matches.length; index++) {
  const match = matches[index]; const page = Number(match[1]);
  const bodyStart = match.index + match[0].length;
  const bodyEnd = index + 1 < matches.length ? matches[index + 1].index : markdown.length;
  const heading = '## Página ' + page + '\n';
  for (const piece of splitText(markdown.slice(bodyStart, bodyEnd), 6000 - heading.length)) pageChunks.push({ page, text: heading + piece });
}
const batches = []; let current = []; let currentPages = []; let currentLength = 0;
for (const chunk of pageChunks) {
  const separator = current.length ? 2 : 0;
  if (current.length && currentLength + separator + chunk.text.length > 6000) {
    batches.push({ pages: currentPages, markdown: current.join('\n\n') });
    current = []; currentPages = []; currentLength = 0;
  }
  current.push(chunk.text); currentLength += (current.length > 1 ? 2 : 0) + chunk.text.length;
  if (!currentPages.length || currentPages[currentPages.length - 1] !== chunk.page) currentPages.push(chunk.page);
}
if (current.length) batches.push({ pages: currentPages, markdown: current.join('\n\n') });
return batches.map((batch, index) => {
  if (batch.markdown.length > 6000) throw new Error('EXTRACAO: lote excede 6000 caracteres');
  const prompt = [
    'Analise integralmente este lote de um documento regulatório. O lote contém as páginas: ' + batch.pages.join(', ') + '.',
    'Use somente este texto. Não invente fatos, páginas, prazos, status ou evidências. Procure todos os atos, produtos, empresas, status regulatórios, exigências, prazos, alterações, riscos e impactos de negócio que estiverem explicitamente documentados.',
    'Retorne JSON válido com a forma {"achados":[{"titulo":"...","fato":"...","status":"...","impacto":"...","risco":"...","acao_recomendada":"...","prioridade":"...","pagina":1,"evidencia":"trecho literal curto"}]}. Se não houver achados, use {"achados":[]}. Cada evidência deve ser uma cópia literal curta deste lote e cada página deve ser uma página presente neste lote.',
    'PROTOCOLO: ' + source.submission_id,
    'LOTE ' + (index + 1) + ' DE ' + batches.length,
    'CONTEXTO DOCUMENTAL:', batch.markdown, 'FIM DO CONTEXTO'
  ].join('\n');
  return { json: { ...batchSource, batch_number: index + 1, batch_count: batches.length, batch_pages: batch.pages, batch_markdown: batch.markdown, batch_prompt: prompt } };
});

const responses = $input.all();
const batches = $('Prepare analysis batches').all();
if (!responses.length || responses.length !== batches.length) throw new Error('IA: resultado ausente em um ou mais lotes; relatório parcial não será gerado');
const merged = new Map();
const pagesProcessed = new Set();
function normalize(value) { return String(value || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim().toLocaleLowerCase('pt-BR'); }
for (let index = 0; index < responses.length; index++) {
  const batch = batches[index].json;
  for (const page of batch.batch_pages || []) pagesProcessed.add(Number(page));
  let raw = String(responses[index].json.response || '').trim();
  raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  let parsed;
  try { parsed = JSON.parse(raw); } catch (error) { throw new Error('VALIDACAO: JSON inválido no lote ' + batch.batch_number + ': ' + error.message); }
  if (!parsed || !Array.isArray(parsed.achados)) throw new Error('VALIDACAO: o lote ' + batch.batch_number + ' não retornou a lista obrigatória de achados');
  for (const finding of parsed.achados) {
    if (!finding || typeof finding !== 'object' || !String(finding.titulo || finding.fato || '').trim() || !Number.isInteger(Number(finding.pagina)) || !String(finding.evidencia || '').trim()) throw new Error('VALIDACAO: achado incompleto no lote ' + batch.batch_number);
    const item = { titulo: String(finding.titulo || '').trim(), fato: String(finding.fato || '').trim(), status: String(finding.status || 'não localizado'), impacto: String(finding.impacto || 'não comprovado'), risco: String(finding.risco || 'não classificado'), acao_recomendada: String(finding.acao_recomendada || 'Conferir o documento original.'), prioridade: String(finding.prioridade || 'informativa'), pagina: Number(finding.pagina), evidencia: String(finding.evidencia).trim() };
    const key = item.pagina + '|' + normalize(item.evidencia);
    if (!merged.has(key)) merged.set(key, item);
  }
}
const source = batches[0].json;
const pages = [...pagesProcessed].sort((a, b) => a - b);
const expectedPages = Number(source.metadata && source.metadata.page_count || 0);
if (pages.length !== expectedPages || pages.some((page, index) => page !== index + 1)) throw new Error('EXTRACAO: nem todas as páginas foram analisadas; relatório parcial não será gerado');
const findings = [...merged.values()];
const reportContext = { type: 'full_document_batched', page_count: expectedPages, pages_processed: pages, batch_count: batches.length, findings_count: findings.length };
const prompt = [
  'Você atua como analista sênior de inteligência regulatória, operações e impacto de mercado. Produza o relatório solicitado somente com base nos achados estruturados de todos os lotes do documento completo.',
  'Não invente fatos, prazos, normas, responsáveis, impacto financeiro, tamanho de mercado ou reação de concorrentes. Diferencie fato documentado, inferência e informação não comprovada. Preserve status deferido, indeferido, cancelado e outros sem reclassificar. Inclua todos os achados fornecidos, sem descartar itens repetidos que tenham evidências diferentes.',
  'Toda afirmação factual e cada achado devem incluir uma referência padronizada em duas linhas: “- Página: N” seguida de “- Evidência literal: \"trecho exato\"”. Copie a evidência exatamente como fornecida. Não crie referências próprias. Se uma informação não aparecer nos achados, escreva “não localizado nos achados analisados” sem afirmar que inexiste no documento.',
  'Retorne somente Markdown em português do Brasil, sem cercas de código ou texto antes do título. Use exatamente as seções: # Relatório Técnico de Inteligência Regulatória; ## 1. Resumo executivo; ## 2. Respostas às perguntas de negócio; ## 3. Escopo e identificação do documento; ## 4. Achados regulatórios; ## 5. Impacto de mercado e comercial; ## 6. Plano de ação recomendado; ## 7. Riscos, contradições e pontos de atenção; ## 8. Limitações e informações não comprovadas; ## 9. Referências de páginas.',
  'Nas seções 2, 6 e 9 use listas com marcadores, sem tabelas Markdown. Na seção 2 escreva uma pergunta e sua resposta por marcador; na seção 6 escreva cada ação, prioridade, justificativa, prazo e responsável por marcador; na seção 9 organize cada referência por marcador. Responda: o que aconteceu, quem é afetado, qual status regulatório, impacto direto, impacto potencial, urgência/prazo, o que fazer e prioridade executiva. Em cada achado inclua fato, status, impacto, risco, prioridade, ação recomendada, página e evidência. Na seção 9 repita as referências padronizadas.',
  'Documento com ' + expectedPages + ' páginas analisadas em ' + batches.length + ' lotes. Protocolo: ' + source.submission_id,
  'ACHADOS CONSOLIDADOS DE TODOS OS LOTES:', JSON.stringify(findings),
  'A leitura e análise cobriram todas as páginas. Não faça afirmações sobre conteúdo que não esteja representado nos achados acima.'
].join('\n');
return [{ json: { ...source, report_prompt: prompt, prompt_version: 'regulatory-extraction-v5-full-document-batched', report_context: reportContext, pages_processed: pages, batch_count: batches.length, findings_count: findings.length } }];

const source = $('Validate report Markdown').item.json; const validation = $json; if (!validation.coverage || !validation.coverage.complete) throw new Error('VALIDACAO: cobertura documental incompleta; relatório parcial não será persistido'); const report = String(validation.validated_report_markdown || ''); if (!report) throw new Error('VALIDACAO: gateway não retornou o relatório conferido'); const confirmed = Number(validation.references && validation.references.confirmed || 0); const total = Number(validation.references && validation.references.total || 0); const pending = Array.isArray(validation.references && validation.references.pending) ? validation.references.pending : []; const coverage = validation.coverage; const lines = ['## 10. Cobertura e referências', '- Páginas analisadas: ' + coverage.processed_pages + '/' + coverage.source_pages + ' (' + Math.round(coverage.ratio * 100) + '%).', '- Referências comprovadas no Markdown original: ' + confirmed + '/' + total + '.']; if (pending.length) { lines.push('- Referências pendentes (não comprovadas; não bloqueiam o envio):'); for (const item of pending) lines.push('  - Página ' + (item.page ?? 'não informada') + ': ' + String(item.reason || 'referência não confirmada') + (item.evidence ? ' — trecho alegado: “' + item.evidence + '”' : '')); } else if (!total) lines.push('- Nenhuma referência literal foi apresentada para conferência.'); const reportWithSignal = report + '

' + lines.join('
'); return [{ json: { ...source, report_markdown: reportWithSignal, report_context: { ...source.report_context, evidence_quality: validation.evidence_quality }, citation_validation: { coverage: validation.coverage, references: validation.references, evidence_quality: validation.evidence_quality }, report_markdown_size_bytes: Buffer.byteLength(reportWithSignal, 'utf8') } }];
